 @Test public void all279OriginalFramesAndAliasesBypassLegacyRotationAndRecolor()throws Exception{
  SourceItemIconRegistry icons=new SourceItemIconRegistry(c);OriginalInventoryV252 originals=new OriginalInventoryV252(c);RpgProgressionState r=new RpgProgressionState();int weapons=0,reagents=0,n=0,assetOnly=0;
  Bitmap gallery=Bitmap.createBitmap(960,1200,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(gallery);out.drawColor(0xff302820);
  for(Iterator<String> it=originals.entries.keys();it.hasNext();){String id=it.next();RpgProgressionState.ItemDefinition d=r.itemDefinitions().get(id);Bitmap raw=originals.get(id),source=icons.get(id),actual=d==null?source:icons.get(d);assertTrue(id,source.sameAs(raw));assertSame(id,source,actual);if(d!=null)assertSame(actual,icons.get(d));else{assetOnly++;assertFalse(r.inventory().containsKey(id));}assertTrue(actual.getWidth()<=32&&actual.getHeight()<=32);
   if(d!=null&&"무기".equals(d.equipSlot))weapons++;if(id.startsWith("IT_REAGENT_"))reagents++;
   SourceItemIconRegistry.draw(out,actual,new RectF(n%20*48,n/20*64,n%20*48+40,n/20*64+40),new Paint());n++;
  }assertEquals(279,n);assertEquals("272current definitions +7retained asset-only IDs",7,assetOnly);assertTrue(weapons>=30);assertTrue(reagents>=3);
  for(Map.Entry<String,String> e:EquipmentIdentityV210.ALIASES.entrySet())if(icons.nativeInventory(e.getValue()))assertSame(e.getKey(),icons.get(e.getKey()),icons.get(e.getValue()));
  assertTrue(icons.nativeInventory("USER_ITEM_20261018_R01881"));assertTrue(icons.nativeInventory("USER_ITEM_20261018_R05502"));save(gallery,"original-inventory-279");
 }
 @Test public void hatsNeverCoverRapidOnEitherBodyAnyFacingOrIdleWalkContact()throws Exception{
  SkillBodyRenderer renderer=new SkillBodyRenderer(c,new SkillPresentationCatalog(c));Bitmap gallery=Bitmap.createBitmap(960,960,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(gallery);int n=0,totalOverlap=0;
  for(String body:new String[]{"mm001","wm001"})for(CharacterRenderer.Direction d:CharacterRenderer.Direction.values())for(String motion:new String[]{"IDLE","WALK","SWING"}){
   String hat="wm001".equals(body)?"wh172":"mh172",rapid="mg146,mc147";
   Bitmap base=render(renderer,body,d,motion,null),hatOnly=render(renderer,body,d,motion,hat),overlay=rapidOverlay(renderer,body,d,motion,rapid),both=render(renderer,body,d,motion,hat+","+rapid);Bitmap expected=hatOnly.copy(Bitmap.Config.ARGB_8888,true);new Canvas(expected).drawBitmap(overlay,0,0,null);int visibleHat=0,visibleRapid=0,overlap=0;
   for(int y=0;y<120;y++)for(int x=0;x<140;x++){int a=base.getPixel(x,y),h=hatOnly.getPixel(x,y),q=overlay.getPixel(x,y);if(h!=a)visibleHat++;if(Color.alpha(q)>0){visibleRapid++;if(h!=a){overlap++;int e=expected.getPixel(x,y),got=both.getPixel(x,y);assertTrue(body+d+motion+" source-alpha Rapid above hat at "+x+","+y,Math.abs(Color.red(e)-Color.red(got))<=1&&Math.abs(Color.green(e)-Color.green(got))<=1&&Math.abs(Color.blue(e)-Color.blue(got))<=1&&Color.alpha(e)==Color.alpha(got));}}}
   assertTrue(body+d+motion+" hat must be rendered",visibleHat>0);assertTrue(body+d+motion+" clip must be rendered",visibleRapid>0);totalOverlap+=overlap;out.drawBitmap(both,n%6*160,n/6*160,null);n++;
  }assertTrue("exercise real overlapping hat pixels",totalOverlap>10);assertEquals(24,n);save(gallery,"rapid-hats-bodies-directions-motions");
 }
 private Bitmap rapidOverlay(SkillBodyRenderer renderer,String body,CharacterRenderer.Direction d,String motion,String rapid)throws Exception{
  SkillPresentationCatalog catalog=new SkillPresentationCatalog(c);String key=catalog.frameKey(body,motion,d,.45f);String[] parts=key.split("/");String group=parts[1];int index=Integer.parseInt(parts[2]);Bitmap out=Bitmap.createBitmap(140,120,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);float x=70,y=102+8*SkillBodyRenderer.SCALE;if(!"02".equals(group)&&(d==CharacterRenderer.Direction.NW||d==CharacterRenderer.Direction.SW))canvas.scale(-1,1,x,y);CharacterRenderer.Pose pose=new CharacterRenderer.Pose(x,102,d,CharacterRenderer.State.IDLE,0,.45f,1,false,rapid,null,null,CharacterRenderer.EffectFamily.NONE);java.lang.reflect.Method method=SkillBodyRenderer.class.getDeclaredMethod("drawRapid",Canvas.class,CharacterRenderer.Pose.class,String.class,String.class,int.class,float.class,float.class,boolean.class);method.setAccessible(true);method.invoke(renderer,canvas,pose,body,group,index,x,y,false);return out;
 }
 private Bitmap render(SkillBodyRenderer renderer,String body,CharacterRenderer.Direction d,String motion,String equipment){Bitmap b=Bitmap.createBitmap(140,120,Bitmap.Config.ARGB_8888);CharacterRenderer.Pose p=new CharacterRenderer.Pose(70,102,d,CharacterRenderer.State.IDLE,0,.45f,1,false,equipment,null,null,CharacterRenderer.EffectFamily.NONE);assertTrue(renderer.draw(new Canvas(b),p,body,motion,.45f));return b;}
